/// 規則である。
pub struct Prod {
    /// 左辺の非終端記号。
    pub lhs: u16,
    /// 右辺の長さ。
    pub len: u8,
    /// 開始の規則か(還元すると受理する)。
    pub start: bool,
    /// `左辺: 右辺の記号…` の綴り。意味の動作を引く鍵である。
    pub key: &'static str,
}

